<script setup lang="ts">
import type { EmotionLabel } from '../../core/models';
import type { ReplacementDraft } from '../useStudio';
const props = defineProps<{ replacement: ReplacementDraft; currentLabel: EmotionLabel }>();
const emit = defineEmits<{ selectFile: [f: File]; updateStart: [n: number]; updateEnd: [n: number]; analyze: []; confirm: [choice: 'keep' | 'accept']; cancel: [] }>();
function pick(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (file) emit('selectFile', file); }
</script>
<template><section class="stage-card replace-panel"><span class="kicker">REPLACE VOICE / 替换声音</span><h2>为「{{ currentLabel }}」换一段声音</h2><p class="replace-note">原作名称与手写气泡会保留，确认替换前不会改动已保存内容。</p><label class="replace-pick">选择新音频<input type="file" accept="audio/*" data-testid="replace-file" @change="pick"></label><p v-if="replacement.busy && !replacement.suggestion">正在处理新声音…</p><template v-else-if="replacement.duration > 0 && !replacement.suggestion"><p v-if="replacement.duration > 10">新声音共 {{ replacement.duration.toFixed(1) }} 秒，超过 10 秒，请先选段。</p><div class="range-pair"><label>起点 {{ replacement.cropStart.toFixed(1) }}s<input type="range" min="0" :max="Math.max(0, replacement.duration - .1)" step=".1" :value="replacement.cropStart" @input="emit('updateStart', Number(($event.target as HTMLInputElement).value))"></label><label>终点 {{ replacement.cropEnd.toFixed(1) }}s<input type="range" :min="Math.min(replacement.duration, replacement.cropStart + .1)" :max="replacement.duration" step=".1" :value="replacement.cropEnd" @input="emit('updateEnd', Number(($event.target as HTMLInputElement).value))"></label></div><button data-testid="replace-analyze" class="acid-button" type="button" @click="emit('analyze')">分析这段新声音 →</button></template><template v-else-if="replacement.suggestion"><div class="emotion-hero"><b>{{ replacement.suggestion.label }}</b><strong>{{ Math.round(replacement.suggestion.confidence * 100) }}%</strong><p>{{ replacement.suggestion.explanation }}</p></div><div class="replace-actions"><button data-testid="confirm-keep" type="button" @click="emit('confirm', 'keep')">沿用原标签「{{ currentLabel }}」</button><button data-testid="confirm-accept" class="acid-button" type="button" @click="emit('confirm', 'accept')">使用新建议「{{ replacement.suggestion.label }}」</button></div></template><button data-testid="cancel-replace" class="replace-cancel" type="button" @click="emit('cancel')">取消替换，保留原声音</button></section></template>
